    public const string PdfUnavailable = "pdf_unavailable";

    /// <summary>Ese mes de la contabilidad está cerrado: no se registra, corrige ni borra nada con fecha en él. Reábralo con POST /v1/accounting/closed_period si hay que corregirlo.</summary>
    public const string PeriodClosed = "period_closed";

    /// <summary>El ticket de compra no se puede guardar, corregir o pedir así (un archivo que no es foto ni PDF, un RFC o uso que no corresponde, una tienda que no factura con Fiscalisto, faltan datos fiscales del emisor…). El mensaje dice por qué.</summary>
    public const string PurchaseReceiptInvalid = "purchase_receipt_invalid";

    /// <summary>La cotización no tiene los datos fiscales del cliente: agrégueselos con POST /v1/quotes/{id} (customer) o mándela con auto_invoice para que los dé al aceptarla.</summary>
    public const string QuoteCustomerMissing = "quote_customer_missing";

    /// <summary>La cotización no se pudo guardar o ya no cambia (aceptada, rechazada o facturada), o no se puede mandar así. El mensaje dice por qué.</summary>
    public const string QuoteInvalid = "quote_invalid";

    /// <summary>La cotización ya se aceptó o se facturó: no se borra. Para cerrar una que no se aceptó, también puede retirarla (POST /v1/quotes/{id}/withdraw).</summary>
    public const string QuoteNotDeletable = "quote_not_deletable";

    /// <summary>La cotización se rechazó, se retiró o venció: no se factura. Si venció o se retiró, cámbiela (es una versión nueva) y vuelva a mandarla.</summary>
    public const string QuoteNotInvoiceable = "quote_not_invoiceable";

    /// <summary>La cotización nunca se envió, así que no se retira ni se marca rechazada: bórrela con DELETE /v1/quotes/{id}.</summary>
    public const string QuoteNotSent = "quote_not_sent";

    /// <summary>Demasiadas solicitudes con la llave. Espere lo que dice Retry-After y reintente.</summary>
    public const string RateLimit = "rate_limit";

    /// <summary>La factura recurrente no se pudo guardar: el día, la hora, la zona o la factura no son válidos. El mensaje dice cuál.</summary>
    public const string RecurringInvalid = "recurring_invalid";

    /// <summary>El emisor ya tiene el máximo de facturas recurrentes activas (25 en pruebas, 5,000 en producción). Pause o borre las que ya no use.</summary>
    public const string RecurringLimit = "recurring_limit";

    /// <summary>Aún no toca timbrar la factura recurrente (409): su next_invoice_on es después de hoy. Para una factura antes de tiempo, use POST /v1/invoices.</summary>
    public const string RecurringNotDue = "recurring_not_due";

    /// <summary>La factura recurrente está en pausa: reanúdela con active: true para timbrarla.</summary>
    public const string RecurringPaused = "recurring_paused";

    /// <summary>Ese emisor no presenta la declaración anual de persona moral del régimen general: es persona física, RESICO, no lucrativa o tiene otro régimen de ISR en Impuestos.</summary>
    public const string RegimeNotApplicable = "regime_not_applicable";

    /// <summary>Otra solicitud con la misma Idempotency-Key sigue en proceso, otra solicitud está cambiando el mismo objeto (dos actualizaciones del mismo cliente a la vez esperan su turno hasta 15 segundos), u otro comprobante que se timbra a la vez no terminó en unos segundos (otro recibo de nómina del mismo empleado, otro pago de la misma factura) (409, con Retry-After). Repítala en un momento con la misma llave: contestará lo mismo.</summary>
    public const string RequestInProgress = "request_in_progress";

    /// <summary>No existe un objeto con ese id (o es de otro emisor o del otro modo).</summary>
    public const string ResourceMissing = "resource_missing";

    /// <summary>La constancia de retenciones no cumple una regla del SAT. No se usó ningún timbre.</summary>
    public const string RetentionInvalid = "retention_invalid";

    /// <summary>Solo quien emitió la constancia puede cancelarla; esta la recibió el emisor.</summary>
    public const string RetentionNotIssued = "retention_not_issued";

    /// <summary>La acción es para constancias timbradas.</summary>
    public const string RetentionNotStamped = "retention_not_stamped";

    /// <summary>El PAC o el SAT no aceptaron la constancia; sat_code trae su código.</summary>
    public const string RetentionRejected = "retention_rejected";

    /// <summary>No existe esa ruta. Revise la dirección y la versión (/v1).</summary>
    public const string RouteNotFound = "route_not_found";

    /// <summary>La regla no se puede guardar así: el mensaje dice por qué (una acción que no va con su trigger, como cost_center en una orden de compra; una etiqueta, etapa o centro de costo que no existe; un campo o un valor que no va con su operador; más de 200 reglas).</summary>
    public const string RuleInvalid = "rule_invalid";

    /// <summary>El pedido está en borrador: confírmelo primero con POST /v1/sales_orders/{id}/confirm.</summary>
    public const string SalesOrderDraft = "sales_order_draft";

    /// <summary>El pedido no se pudo guardar o no se puede hacer eso en su estado (por ejemplo, ya no queda nada por entregar o facturar, o está cancelado). El mensaje dice por qué.</summary>
    public const string SalesOrderInvalid = "sales_order_invalid";

    /// <summary>Solo se borra un pedido en borrador; uno confirmado se cancela con POST /v1/sales_orders/{id}/cancel.</summary>
    public const string SalesOrderNotDeletable = "sales_order_not_deletable";

    /// <summary>No se pudo crear el entorno de prueba: falta su nombre o la cuenta ya tiene 25 (borre uno que ya no use).</summary>
    public const string SandboxInvalid = "sandbox_invalid";

    /// <summary>Solo se marca como pagada una factura de ingreso recibida y vigente: una PPD que siga por pagar, o una PUE para anotar de dónde salió el dinero. El mensaje dice por qué esta no.</summary>
    public const string SatInvoiceNotMarkable = "sat_invoice_not_markable";

    /// <summary>Las declaraciones de ese emisor se consultaron en el SAT hace menos de 10 minutos (cada consulta entra al SAT con su e.firma). Retry-After dice cuántos segundos faltan; lo que ya trajo está en GET /v1/sat_declarations.</summary>
    public const string SatRefreshTooSoon = "sat_refresh_too_soon";

    /// <summary>El SAT rechazó la solicitud de descarga. El mensaje trae su motivo, por ejemplo que ya se pidió el mismo periodo con los mismos filtros demasiadas veces (el SAT pone un límite de por vida).</summary>
    public const string SatRequestRejected = "sat_request_rejected";

    /// <summary>El SAT no contestó o no dejó entrar con la e.firma del emisor. El mensaje trae lo que dijo; no se usó ningún timbre. Reintente en 10 minutos.</summary>
    public const string SatUnavailable = "sat_unavailable";

    /// <summary>La búsqueda de query no se entiende: un campo por el que no se busca, un operador que no va con ese campo, una comilla sin cerrar, AND y OR juntos o más de 10 cláusulas. El mensaje dice dónde.</summary>
    public const string SearchQueryInvalid = "search_query_invalid";

    /// <summary>Ese cambio ya no se puede deshacer: ya se deshizo, el ajuste cambió otra vez después (deshaga primero el más reciente) o ya no tiene el valor que dejó ese cambio.</summary>
    public const string SettingChangeNotUndoable = "setting_change_not_undoable";

    /// <summary>Demasiados timbres seguidos del mismo emisor. Espere lo que dice Retry-After; para muchas facturas use POST /v1/invoice_batches, y para una nómina POST /v1/payroll_batches.</summary>
    public const string StampRateLimit = "stamp_rate_limit";

    /// <summary>Esa tienda ya está conectada a este emisor.</summary>
    public const string StoreAlreadyConnected = "store_already_connected";

    /// <summary>La tienda no aceptó la conexión o no respondió como se esperaba (llaves equivocadas, permisos read_orders/write_orders que faltan, una tienda que no vende en pesos). El mensaje dice qué contestó.</summary>
    public const string StoreConnectionFailed = "store_connection_failed";

    /// <summary>La tienda se desconectó: conéctela otra vez con POST /v1/store_connections.</summary>
    public const string StoreDisconnected = "store_disconnected";

    /// <summary>El vendedor aún no autoriza la conexión en authorize_url.</summary>
    public const string StoreNotAuthorized = "store_not_authorized";

    /// <summary>Esa plataforma aún no está disponible en Fiscalisto.</summary>
    public const string StorePlatformUnavailable = "store_platform_unavailable";

    /// <summary>Los complementos de pago y las notas de crédito no se sustituyen: se cancelan y se emite otro. Un recibo de nómina se sustituye con POST /v1/payroll_receipts/external y replaces.</summary>
    public const string SubstitutionUnsupported = "substitution_unsupported";

    /// <summary>La factura del proveedor no admite eso en su estado (por ejemplo, programar una que no está aprobada, una fecha de pago pasada o marcar pagada una ya pagada), o el SAT la reporta cancelada. El mensaje dice por qué.</summary>
    public const string SupplierInvoiceInvalid = "supplier_invoice_invalid";

    /// <summary>Ya hay una etiqueta con ese nombre (sin importar mayúsculas ni acentos): el mensaje trae su id (tag_…).</summary>
    public const string TagExists = "tag_exists";

    /// <summary>La empresa llegó a 200 etiquetas: borre las que ya no use.</summary>
    public const string TagLimit = "tag_limit";

    /// <summary>El cambio da, quita o toca un permiso delicado (equipo, credenciales, seguridad o plan), o nombra a un propietario: pide confirmar la identidad de quien lo hace, y eso se hace en la app, en Ajustes › Miembros o Ajustes › Roles.</summary>
    public const string TeamChangeRequiresApp = "team_change_requires_app";

    /// <summary>El cambio no se puede: la persona ya es miembro, quedaría la empresa sin propietario, ya hay un rol con ese nombre, el rol lo tiene alguien, o se mandaron demasiadas invitaciones hoy. El mensaje dice cuál.</summary>
    public const string TeamInvalid = "team_invalid";

    /// <summary>La llave actúa como la persona que la creó, con su acceso en la empresa: le falta el permiso para esto, o lo que pide daría más de lo que ella tiene, o ya no es miembro.</summary>
    public const string TeamPermissionDenied = "team_permission_denied";

    /// <summary>El plan de la empresa ya tiene todos sus usuarios (miembros más invitaciones pendientes). Cambie de plan en Ajustes › Plan y pagos o quite a alguien.</summary>
    public const string TeamSeatLimit = "team_seat_limit";

    /// <summary>El reloj se está adelantando en otra solicitud (409, con Retry-After). Espere a test_clock.ready y repita.</summary>
    public const string TestClockAdvancing = "test_clock_advancing";

    /// <summary>El emisor ya tiene un reloj de prueba: adelántelo, o bórrelo para volver a la hora real.</summary>
    public const string TestClockExists = "test_clock_exists";

    /// <summary>frozen_time no sirve: no es una fecha y hora ISO 8601, es anterior a la hora del reloj (solo avanza) o va más de dos años adelante de la hora real.</summary>
    public const string TestClockInvalid = "test_clock_invalid";

    /// <summary>El emisor no tiene reloj de prueba: créelo con POST /v1/issuers/{id}/test_clock.</summary>
    public const string TestClockMissing = "test_clock_missing";

    /// <summary>Los relojes de prueba son de emisores de prueba: use su llave fk_test_ y un emisor de pruebas.</summary>
    public const string TestClockUnsupported = "test_clock_unsupported";

    /// <summary>Esto solo existe en pruebas (como reiniciar los datos de prueba): use su llave fk_test_.</summary>
    public const string TestModeOnly = "test_mode_only";

    /// <summary>Ese folio ya está registrado para el emisor con otro total o con otra propina (409). Con el mismo total se contesta el ticket que ya existe.</summary>
    public const string TicketFolioTaken = "ticket_folio_taken";

    /// <summary>El ticket no se pudo registrar: el folio trae caracteres no válidos, la fecha de venta está en el futuro o es de hace más de un año, el producto ya no está en el catálogo… El mensaje dice cuál.</summary>
    public const string TicketInvalid = "ticket_invalid";

    /// <summary>El ticket ya se facturó o entró en una factura global: no se puede cancelar.</summary>
    public const string TicketNotPending = "ticket_not_pending";

    /// <summary>La API no contestó a tiempo (connection_error). Con lo que timbra, repita con la misma Idempotency-Key para saber si se timbró.</summary>
    public const string Timeout = "timeout";

    /// <summary>Mande el cuerpo con Content-Type: application/json.</summary>
    public const string UnsupportedContentType = "unsupported_content_type";
}
